process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 3 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
echo RANGE_START=$(p 1.1.1.1:80)
echo RANGE_END=$(p 1.1.1.1:443)
echo RANGE_BELOW=$(p 1.1.1.1:79)
echo RANGE_ABOVE=$(p 1.1.1.1:444)
echo RANGE_OUTSIDE=$(p 1.1.1.1:853)
echo LIST_FIRST=$(p 8.8.8.8:443)
echo LIST_SECOND=$(p 8.8.8.8:853)
echo LIST_OTHER=$(p 8.8.8.8:53)
echo ALL_PORTS_443=$(p 9.9.9.9:443)
echo ALL_PORTS_853=$(p 9.9.9.9:853)
echo UNLISTED=$(p 1.0.0.1:443)
